import std.collection.HashMap
import std.time.DateTime
import std.option.Option
import std.option.None

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    private let apiPrefix = "/api"
    private let loginPath = "/login"

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        /*
        Filter the incoming request based on certain rules and conditions.
        :param request: HashMap<String, Any>, the incoming request details
        :return: Bool, true if the request is allowed, false otherwise
        */
        let path = request.get("path") as? String ?? ""
        let method = request.get("method") as? String ?? ""

        if path == loginPath && method == "POST" {
            return true
        }

        if is_start_with(request_uri: path) {
            if let userOpt = get_jwt_user(request: request) {
                if userOpt.get("user") != None {
                    set_current_user_info_and_log(user: userOpt as HashMap<String, Any>)
                    return true
                }
            }
        }

        return false
    }

    public func is_start_with(request_uri: String): Bool {
        /*
        Check if the request URI starts with certain prefixes.
        Currently, the prefixes being checked are "/api" and "/login".
        :param request_uri: String, the URI of the request
        :return: Bool, true if the URI starts with certain prefixes, false otherwise
        */
        return request_uri.startsWith(apiPrefix) || request_uri == loginPath
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        /*
        Get the user information from the JWT token in the request.
        :param request: HashMap<String, Any>, the incoming request details
        :return: HashMap<String, Any> or None, the user information if the token is valid, None otherwise
        */
        if let headers = request.get("headers") as? HashMap<String, Any> {
            if let auth = headers.get("Authorization") as? HashMap<String, Any> {
                if let jwt = auth.get("jwt") as? String {
                    // Simple JWT validation - in real implementation should verify signature
                    let expectedPrefix = (auth.get("user") as? HashMap<String, Any>)?.get("name") as? String ?? ""
                    let today = DateTime.now().format("yyyy-MM-dd")
                    if jwt.startsWith(expectedPrefix + today) {
                        return auth.get("user") as Option<HashMap<String, Any>>
                    }
                }
            }
        }
        return None
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        /*
        Set the current user information and log the access.
        :param user: HashMap<String, Any>, the user information
        :return: Unit
        */
        // In real implementation, would set current user in context and log
        let name = user.get("name") as? String ?? "unknown"
        let address = user.get("address") as? String ?? "unknown"
        print("User accessed: \(name) from \(address) at \(DateTime.now().format("yyyy-MM-dd HH:mm:ss"))")
    }
}

