public class CircularLayoutAlgorithm2D < V, E > <: BaseLayoutAlgorithm2D < V, E > where E <: Equatable < E > & ToString & Hashable, V <: Equatable < V > & ToString & Hashable {
    let radius: Float64
    let comparator: ToleranceDoubleComparator = ToleranceDoubleComparator()
    let vertexComparator:?(V, V) -> Ordering
    public init() {
        this(0.5)
    }
    public init(radius: Float64) {
        this.radius = radius
        this.vertexComparator = None
    }
    public init(radius: Float64, vertexComparator:?(V, V) -> Ordering) {
        this.radius = radius
        if(comparator.compare(radius, 0.0) <= 0) {
            throw IllegalArgumentException("The radius must be positive")
        }
        this.vertexComparator = vertexComparator
    }
    public func layout(graph: Graph < V, E >, model: LayoutModel2D < V >) {
        super.layout(graph, model)
        let drawableArea = model.getDrawableArea()
        let width = drawableArea.getWidth()
        if(comparator.compare(2.0 * radius, width) > 0) {
            throw IllegalArgumentException("Circle does not fit into drawable area width")
        }
        let height = drawableArea.getHeight()
        if(comparator.compare(2.0 * radius, height) > 0) {
            throw IllegalArgumentException("Circle does not fit into drawable area height")
        }
        let minX = drawableArea.getMinX()
        let minY = drawableArea.getMinY()
        let n = graph.vertexSet().size
        let angleStep = 2.0 * Float64.PI / Float64(n)
        let vertexStream = graph.vertexSet().toArray()
        if(let Some(vertexComparator) <- vertexComparator) {
            vertexStream.sortBy(stable: false, comparator: vertexComparator)
        }
        var i = 0.0
        for(v in vertexStream) {
            let x = radius * cos(angleStep * i) + width / 2.0
            let y = radius * sin(angleStep * i) + height / 2.0
            model.put(v, Point2D(minX + x, minY + y))
            i += 1.0
        }
    }
}
