import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        func factorial(k: Int64): Int64 {
            if k <= 1 { return 1 }
            return k * factorial(k: k - 1)
        }
        let actual_m = m.getOrElse(n)
        if actual_m > n || actual_m < 0 { return 0 }
        return factorial(k: n) / factorial(k: n - actual_m)
    }

    public static func count_all(n: Int64): Int64 {
        func factorial(k: Int64): Int64 {
            if k <= 1 { return 1 }
            return k * factorial(k: k - 1)
        }
        var total: Int64 = 0
        for m in 1..n+1 {
            total += factorial(k: n) / factorial(k: n - m)
        }
        return total
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        let actual_m = m.getOrElse(this.datas.size)
        if actual_m <= 0 || actual_m > this.datas.size { return result }

        let indices = ArrayList<Int64>(0..this.datas.size)
        select_permutations(prefix: ArrayList<Int64>(), remaining: indices, m: actual_m, result: result)

        let indexed_perms = ArrayList<ArrayList<Int64>>(result)
        let final_result = ArrayList<ArrayList<Int64>>()
        for perm in indexed_perms {
            let data_perm = ArrayList<Int64>()
            for i in 0..perm.size {
                data_perm.add(this.datas[perm[i].toInt()])
            }
            final_result.add(data_perm)
        }
        return final_result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        let max_m = this.datas.size
        for m in 1..max_m+1 {
            let m_perms = this.select(m: m)
            for perm in m_perms {
                result.add(perm)
            }
        }
        return result
    }

    public static func factorial(n: Int64): Int64 {
        if n <= 1 { return 1 }
        return n * factorial(n: n - 1)
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if prefix.size == m {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for i in 0..remaining.size {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m, result)
        }
    }
}

