        let opParser = addOp.or(subOp)
        return opParser.flatMap({ op: String => wrap(parseTerm()).flatMap({ right: Expr => let result = match(op) {
                    case "add" => Expr.Add(left, right)
                    case "sub" => Expr.Subtract(left, right)
                    case _ => left
