            throw Exception("存款金额必须大于0")
        }
        let event = MoneyDepositedEvent(id, amount, version + 1)
        applyEvent(event)
        uncommittedEvents.add(event)
    }
    public func applyEvent(event: DomainEvent): Unit {
        match(event.getEventType()) {
            case "AccountCreated" => match(event as AccountCreatedEvent) {
                case Some(createdEvent) => this.balance = createdEvent.initialBalance
                this.version = event.getVersion()
                case None =>()
            }
            case "MoneyDeposited" => match(event as MoneyDepositedEvent) {
                case Some(depositEvent) => this.balance += depositEvent.amount
                this.version = event.getVersion()
                case None =>()
            }
            case _ => throw Exception("未知事件类型: ${event.getEventType()}")
        }
    }
    public func getUncommittedEvents(): Array < DomainEvent > {
        return uncommittedEvents.toArray()
    }
    public func markEventsAsCommitted(): Unit {
        uncommittedEvents.clear()
    }
    public func loadFromSnapshot(snapshot: Snapshot): Unit {
        this.version = snapshot.getVersion()
    }
