import std.convert.Parsable

class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let len1 = num1.size
        let len2 = num2.size
        let maxLen = if(len1 > len2) len1 else len2
        let num1Str = num1.reverse()
        let num2Str = num2.reverse()
        let builder = StringBuilder()
        var carry = 0
        for(i in 0 .. maxLen) {
            let digit1 = if(i < len1) Int32.parse(num1Str[i..i+1]) else 0
            let digit2 = if(i < len2) Int32.parse(num2Str[i..i+1]) else 0
            let sum = digit1 + digit2 + carry
            carry = sum / 10
            builder.append((sum % 10).toString())
        }
        if(carry > 0) {
            builder.append(carry.toString())
        }
        return builder.toString().reverse()
    }

    public static func subtract(num1: String, num2: String): String {
        let isNegative = num1 < num2
        let a = if(isNegative) num2 else num1
        let b = if(isNegative) num1 else num2
        let len1 = a.size
        let len2 = b.size
        let aStr = a.reverse()
        let bStr = b.reverse()
        let builder = StringBuilder()
        var borrow = 0
        for(i in 0 .. len1) {
            let digit1 = Int32.parse(aStr[i..i+1])
            let digit2 = if(i < len2) Int32.parse(bStr[i..i+1]) else 0
            var diff = digit1 - digit2 - borrow
            if(diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            builder.append(diff.toString())
        }
        var result = builder.toString().reverse()
        var i = 0
        while(i < result.size && result[i] == '0') {
            i += 1
        }
        result = result[i..]
        if(result.size == 0) {
            return "0"
        }
        return if(isNegative) "-" + result else result
    }

    public static func multiply(num1: String, num2: String): String {
        if(num1 == "0" || num2 == "0") {
            return "0"
        }
        let len1 = num1.size
        let len2 = num2.size
        let num1Str = num1.reverse()
        let num2Str = num2.reverse()
        let results = Array<Int32>(repeating: 0, size: len1 + len2)
        for(i in 0 .. len1) {
            for(j in 0 .. len2) {
                let digit1 = Int32.parse(num1Str[i..i+1])
                let digit2 = Int32.parse(num2Str[j..j+1])
                results[i + j] += digit1 * digit2
                if(results[i + j] >= 10) {
                    results[i + j + 1] += results[i + j] / 10
                    results[i + j] = results[i + j] % 10
                }
            }
        }
        var k = len1 + len2 - 1
        while(k > 0 && results[k] == 0) {
            k -= 1
        }
        let builder = StringBuilder()
        for(i in 0 .. k + 1) {
            builder.append(results[i].toString())
        }
        return builder.toString().reverse()
    }
}

