import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {

    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
        this.date = date
        this.start_time = start_time
        this.end_time = end_time
        this.description = description
    }

    public override operator func != (that: Event): Bool {
        return this.date != that.date || this.start_time != that.start_time || this.end_time != that.end_time || this.description != that.description
    }

    public override operator func == (that: Event): Bool {
        return this.date == that.date && this.start_time == that.start_time && this.end_time == that.end_time && this.description == that.description
    }
}

class CalendarUtil {

    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        events.add(event)
    }

    public func remove_event(event: Event): Unit {
        for (i in 0..<events.size()) {
            if events.get(i) == event {
                events.remove(i)
                break
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let filtered_events = ArrayList<Event>()
        for (event in events) {
            if event.date.sameDate(date) {
                filtered_events.add(event)
            }
        }
        return filtered_events
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in events) {
            if (start_time >= event.start_time && start_time < event.end_time) || 
               (end_time > event.start_time && end_time <= event.end_time) || 
               (start_time <= event.start_time && end_time >= event.end_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let sorted_events = this.get_events(date).sort { a, b -> a.start_time < b.start_time }
        let slots = ArrayList<(DateTime, DateTime)>()
        let day_end = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, 
                                  hour: 23, minute: 59, second: 59)
        var current_time = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)

        for (event in sorted_events) {
            if event.start_time > current_time {
                slots.add((current_time, event.start_time))
            }
            current_time = event.end_time
        }

        if (current_time < day_end) {
            slots.add((current_time, day_end))
        }

        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let upcoming_events = ArrayList<Event>()
        let now = DateTime.now()
        let future_events = events.filter { event -> event.start_time >= now }.sort { a, b -> a.start_time < b.start_time }

        for (i in 0..<$num_events) {
            if i < future_events.size() {
                upcoming_events.add(future_events[i])
            }
        }

        return upcoming_events
    }
}

