            }
            for(i in SIZE_RADIX - 1 ..= 0) {
                cnt[(list[i] >> shift) & MASK] -= 1
                tempArray[cnt[(list[i] >> shift) & MASK]] = list[i]
            }
        }
        for(i in 0 ..= n - 1) {
            list[i] = tempArray[i]
        }
