import std.collection.ArrayList
import std.collection.HashMap

class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        let name = student.get("name").getOrThrow({ => ToolException("Student must have a name") }).asString().getValue()
        for s in this.students {
            if s.get("name").map({ v => v.asString().getValue() }).getOrElse({ => "" }) == name {
                return 0
            }
        }
        this.students.add(student)
        this.students_registration_classes.put(name, ArrayList<String>())
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if !this.students_registration_classes.containsKey(student_name) {
            this.students_registration_classes.put(student_name, ArrayList<String>())
        }
        let classes = this.students_registration_classes.get(student_name).getOrThrow({ => ToolException("Student not found") })
        if !classes.contains(class_name) {
            classes.add(class_name)
        }
        return classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let result = ArrayList<String>()
        for s in this.students {
            if s.get("major").map({ v => v.asString().getValue() }).getOrElse({ => "" }) == major {
                result.add(s.get("name").getOrThrow({ => ToolException("Student must have a name") }).asString().getValue())
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        let majors = HashSet<String>()
        for s in this.students {
            if let major = s.get("major") {
                majors.add(major.asString().getValue())
            }
        }
        return ArrayList<String>(majors.toList())
    }

    public func get_most_popular_class_in_major(major: String): String {
        let major_students = this.get_students_by_major(major)
        let class_counts = HashMap<String, Int64>()

        for student_name in major_students {
            if let classes = this.students_registration_classes.get(student_name) {
                for class_name in classes {
                    let count = class_counts.get(class_name).getOrElse({ => 0 }) + 1
                    class_counts.put(class_name, count)
                }
            }
        }

        if class_counts.size() == 0 {
            return ""
        }

        var most_popular: String = ""
        var max_count: Int64 = -1
        for (class_name, count) in class_counts {
            if count > max_count {
                max_count = count
                most_popular = class_name
            }
        }
        return most_popular
    }
}

