import std.collection.ArrayList

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if m < 0 || m > n {
            return 0
        }
        return factorial(n: n) / (factorial(n: m) * factorial(n: n - m))
    }

    public static func count_all(n: Int64): Int64 {
        let max = 18446744073709551615
        var total = Int64(0)
        for m in 1..n + 1 {
            let combinations = count(n: n, m: m)
            if total + combinations > max {
                return max
            }
            total += combinations
        }
        return total
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        if m < 1 || m > datas.size {
            return result
        }
        let temp = ArrayList<String>(Array<String>(CangjieInt(m).toInt(), repeat: ""))
        _select(dataIndex: 0, resultList: temp, resultIndex: 0, result: result, selectNum: m)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for m in 1..datas.size + 1 {
            let combinations = select(m: CangjieInt(m).toInt64())
            for combination in combinations {
                result.add(elem: combination)
            }
        }
        return result
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>, selectNum: Int64): Unit {
        if resultIndex == selectNum {
            let newCombination = ArrayList<String>()
            for i in 0..selectNum {
                newCombination.add(elem: resultList[i as Int])
            }
            result.add(elem: newCombination)
            return
        }
        for i in dataIndex..datas.size {
            resultList[resultIndex as Int] = datas[i as Int]
            _select(dataIndex: i + 1, resultList: resultList, resultIndex: resultIndex + 1, result: result, selectNum: selectNum)
        }
    }
}

