import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = try OpenFile.forRead(file_name)
        let reader = BufferedReader(file)
        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        // Read title
        if var firstLine = try reader.readLine() {
            title = parseCsvLine(firstLine)
        }

        // Read data
        while var line = try reader.readLine() {
            let row = parseCsvLine(line)
            data.add(row)
        }

        try reader.close()
        return (title, data)
    }

    private func parseCsvLine(line: String): ArrayList<String> {
        var fields = ArrayList<String>()
        var currentField = StringBuilder()
        var inQuotes = false

        for char in line {
            if char == '"' {
                inQuotes = !inQuotes
            } else if char == ',' && !inQuotes {
                fields.add(currentField.toString())
                currentField.clear()
            } else {
                currentField.append(char)
            }
        }

        fields.add(currentField.toString())
        return fields
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        if data.isEmpty() {
            return 0
        }

        try {
            let file = OpenFile.forWrite(file_name)
            let writer = BufferedWriter(file)

            // Write title (first row)
            if var title = data.get(0) {
                if title.size() > 0 {
                    try writer.write(title.get(0)!)
                    for i in 1..<title.size() {
                        try writer.write(",")
                        try writer.write(title.get(i)!)
                    }
                    try writer.write("\n")
                }
            }

            // Write data rows
            for i in 1..<data.size() {
                if var row = data.get(i) {
                    if row.size() > 0 {
                        try writer.write(row.get(0)!)
                        for j in 1..<row.size() {
                            try writer.write(",")
                            try writer.write(row.get(j)!)
                        }
                        try writer.write("\n")
                    }
                }
            }

            try writer.close()
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        var (title, data) = try read_csv(save_file_name)
        if N < 0 || N >= title.size() {
            return 0
        }

        // Create new data with ony Nth column capitalized
        let newTitle = ArrayList<String>()
        newTitle.add(title.get(N.toInt())!)

        let newData = ArrayList<ArrayList<String>>()
        for row in data {
            if row.size() > N {
                let newRow = ArrayList<String>()
                if let value = row.get(N.toInt()) {
                    newRow.add(value.toUpperCase())
                    newData.add(newRow)
                }
            }
        }

        // Create new file name with _process suffix
        let dotIndex = save_file_name.lastIndexOf('.')
        let newFileName = if dotIndex != -1 {
            save_file_name.substring(0, dotIndex) + "_process" + save_file_name.substring(dotIndex)
        } else {
            save_file_name + "_process"
        }

        return write_csv(
            data: newData,
            file_name: newFileName
        )
    }
}

