import std.collection.HashMap
import std.collection.ArrayList
import std.math.round
import std.math.abs
import std.sort.sort

class DataStatistics {

    /*
    This is a class for performing data statistics, supporting to calculate the mean, median, and mode of a given data set.
    */

    public func mean(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the average value of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the mean value
        >>> ds = DataStatistics()
        >>> ds.mean(ArrayList<Int64>([1, 2, 3, 4, 5]))
        3.00
        */
        if(data.size == 0) {
            return 0.00
        }
        var sum: Int64 = 0
        for(i in 0 ..< data.size) {
            sum += data[i]
        }
        let meanValue: Float64 = Float64(sum) / Float64(data.size)
        return round(meanValue * 100) / 100
    }

    public func median(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the median of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the median value
        >>> ds = DataStatistics()
        >>> ds.median(ArrayList<Int64>([2, 5, 1, 3, 4]))
        3.00
        */
        if(data.size == 0) {
            return 0.00
        }
        let sortedData: ArrayList<Int64> = ArrayList<Int64>(data)
        sort(sortedData)
        if(sortedData.size % 2 == 1) {
            let medianValue: Float64 = Float64(sortedData[(sortedData.size - 1) / 2])
            return round(medianValue * 100) / 100
        } else {
            let a: Int64 = sortedData[sortedData.size / 2 - 1]
            let b: Int64 = sortedData[sortedData.size / 2]
            let medianValue: Float64 = (Float64(a) + Float64(b)) / 2.0
            return round(medianValue * 100) / 100
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        /*
        Calculate the mode of a set of data
        :param data:ArrayList<Int64>, data list
        :return:ArrayList<Int64>, the mode
        >>> ds = DataStatistics()
        >>> ds.mode(ArrayList<Int64>([2, 2, 3, 3, 4]))
        [2, 3]
        */
        if(data.size == 0) {
            return ArrayList<Int64>()
        }
        let counts: HashMap<Int64, Int64> = HashMap<Int64, Int64>()
        for(i in 0 ..< data.size) {
            let key: Int64 = data[i]
            if(counts.containsKey(key)) {
                counts.put(key, counts[key]! + 1)
            } else {
                counts.put(key, 1)
            }
        }
        var maxCount: Int64 = 0
        for(count in counts.values()) {
            if(count > maxCount) {
                maxCount = count
            }
        }
        let modes: ArrayList<Int64> = ArrayList<Int64>()
        for(entry in counts.entrySet()) {
            if(entry.value == maxCount) {
                modes.add(entry.key)
            }
        }
        if(modes.size == counts.size) {
            return ArrayList<Int64>()
        }
        sort(modes)
        return modes
    }
}

