class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for(num in data) {
            sum += num
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        var min: Float64 = data[0]
        for(num in data) {
            if(num < min) {
                min = num
            }
        }
        return min
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        var max: Float64 = data[0]
        for(num in data) {
            if(num > max) {
                max = num
            }
        }
        return max
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let mean: Float64 = get_sum() / Float64(data.size)
        var sum_sqr_diff: Float64 = 0.0
        for(num in data) {
            sum_sqr_diff += (num - mean) * (num - mean)
        }
        return round((sum_sqr_diff / Float64(data.size)) * 100) / 100
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        return round(sqrt(get_variance()) * 100) / 100
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        let mean: Float64 = get_sum() / Float64(data.size)
        var numerator: Float64 = 0.0
        var denom_x: Float64 = 0.0
        var denom_y: Float64 = 0.0
        for(num in data) {
            let diff: Float64 = num - mean
            numerator += diff * diff
            denom_x += diff * diff
            denom_y += diff * diff
        }
        if(denom_x == 0.0 || denom_y == 0.0) {
            return 0.0
        }
        let correlation = numerator / sqrt(denom_x * denom_y)
        // For single dataset correlation with itself is 1.0
        // The current implementation assumes comparing with identical dataset
        // In practice, correlation requires two datasets
        return round(correlation * 100) / 100
    }
}

