public class PythagoreanServiceImpl <: IPythagoreanService {
    public func findTripletsWithMaxFactorAndSum(maxFactor: Int, sum: Int): ArrayList < PythagoreanTriplet > {
        let result = ArrayList < PythagoreanTriplet >()
        let limitF = Float64(sum) /(1.0 + 1.0 + sqrt(2.0))
        let limit = Int64(floor(limitF))
        for(a in 1 .. limit) {
            let numerator = a * a + Int64(pow(Float64(sum - a), 2.0))
            let denominator = 2 *(sum - a)
            if(numerator % denominator == 0) {
                let c = numerator / denominator
                let b = sum - a - c
                if(c <= maxFactor && b > 0) {
                    result.append(PythagoreanTriplet.create(a, b, c))
                }
            }
        }
        return result
    }
