import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        if(data1.size != data2.size || data1.size == 0) {
            return 0.0
        }
        var sum1: Float64 = 0.0
        var sum2: Float64 = 0.0
        for(i in 0 .. data1.size) {
            sum1 += data1[i]
            sum2 += data2[i]
        }
        let mean1: Float64 = sum1 / Float64(data1.size)
        let mean2: Float64 = sum2 / Float64(data2.size)
        var cov: Float64 = 0.0
        var var1: Float64 = 0.0
        var var2: Float64 = 0.0
        for(i in 0 .. data1.size) {
            let diff1: Float64 = data1[i] - mean1
            let diff2: Float64 = data2[i] - mean2
            cov += diff1 * diff2
            var1 += diff1 * diff1
            var2 += diff2 * diff2
        }
        let std1: Float64 = sqrt(var1 / Float64(data1.size))
        let std2: Float64 = sqrt(var2 / Float64(data2.size))
        if(std1 == 0.0 || std2 == 0.0) {
            return 0.0
        }
        return cov / (std1 * std2 * Float64(data1.size))
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        if(data.size < 3) {
            return 0.0
        }
        var sum: Float64 = 0.0
        for(value in data) {
            sum += value
        }
        let mean: Float64 = sum / Float64(data.size)
        var varSum: Float64 = 0.0
        for(value in data) {
            varSum += (value - mean) * (value - mean)
        }
        let variance: Float64 = varSum / Float64(data.size)
        if(variance == 0.0) {
            return 0.0
        }
        let std: Float64 = sqrt(variance)
        var skewSum: Float64 = 0.0
        for(value in data) {
            skewSum += pow(value - mean, 3.0)
        }
        return (skewSum / Float64(data.size)) / pow(std, 3.0)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        if(data.size < 4) {
            return 0.0
        }
        var sum: Float64 = 0.0
        for(value in data) {
            sum += value
        }
        let mean: Float64 = sum / Float64(data.size)
        var varSum: Float64 = 0.0
        for(value in data) {
            varSum += (value - mean) * (value - mean)
        }
        let variance: Float64 = varSum / Float64(data.size)
        if(variance == 0.0) {
            return 0.0
        }
        let std: Float64 = sqrt(variance)
        var kurtSum: Float64 = 0.0
        for(value in data) {
            kurtSum += pow(value - mean, 4.0)
        }
        let result: Float64 = (kurtSum / Float64(data.size)) / pow(std, 4.0)
        return result - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let results: ArrayList<Float64> = ArrayList<Float64>(data.size)
        let variance: Float64 = sigma * sigma
        if(variance <= 0.0) {
            for(_ in 0 .. data.size) {
                results.append(0.0)
            }
            return results
        }
        let normalization: Float64 = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        for(value in data) {
            let exponent: Float64 = -((value - mu) * (value - mu)) / (2.0 * variance)
            results.append(normalization * exp(exponent))
        }
        return results
    }
}

