            return None
        }
        let vertexList: ArrayList < V >= reconstructTour(vertexToIntegerMapping.getIndexList(), w, c)
        return vertexListToTour(vertexList, graph)
    }
    private func computeMinimumWeights(vertexMap: Map < V, Int64 >, graph: Graph < V, E >): ArrayList < ArrayList < Float64 >> {
        let n: Int64 = vertexMap.size
        let w: ArrayList < ArrayList < Float64 >>= ArrayList < ArrayList < Float64 >>(n, { _ => ArrayList < Float64 >(n, { _ => Float64.Inf }) })
        for(e in graph.edgeSet()) {
            let source: V = graph.getEdgeSource(e)
            let target: V = graph.getEdgeTarget(e)
            let u: Int64 = vertexMap[source]
            let v: Int64 = vertexMap[target]
            w[u][v] = min(w[u][v], graph.getEdgeWeight(e))
            if(graph.getType().isUndirected()) {
                w[v][u] = min(w[v][u], graph.getEdgeWeight(e))
            }
        }
        return w
    }
    private func reconstructTour(indexList: ArrayList < V >, w: ArrayList < ArrayList < Float64 >>, c: ArrayList < ArrayList < Float64 >>): ArrayList < V > {
        let n: Int64 = indexList.size
        let vertexList: ArrayList < V >= ArrayList < V >(n)
        var lastNode: Int64 = 0
        var lastState: Int64 = 1
        vertexList.append(indexList[lastNode])
        for(_ in 1 .. n) {
            var nextNode: Int64 = - 1
            for(node in 1 .. n) {
                let t: Float64 = c[node][lastState ^(1 << node)] + w[lastNode][node]
                if((lastState &(1 << node)) == 0 && w[lastNode][node] != Float64.Max && c[node][lastState ^(1 << node)] != Float64.Min &&(t == c[lastNode][lastState])) {
                    nextNode = node
                    break
                }
            }
            if(nextNode == - 1) {
