public class HeldKarpTSP < V, E > <: HamiltonianCycleAlgorithmBase < V, E > where E <: Equatable < E > & ToString & Hashable, V <: Equatable < V > & ToString & Hashable {
    private func memo(previousNode: Int64, state: Int64, c: ArrayList < ArrayList < Float64 >>, w: ArrayList < ArrayList < Float64 >>): Float64 {
        if(c[previousNode][state] != Float64.Min) {
            return c[previousNode][state]
        }
        var totalCost: Float64 = Float64.Max
        if(state ==(1 << w.size) - 1) {
            if(w[previousNode][0] != Float64.Max) {
                totalCost = w[previousNode][0]
            }
        }
        else {
            for(i in 0 .. w.size) {
                if(((state >> i) & 1) == 0 && w[previousNode][i] != Float64.Max) {
                    totalCost = min(totalCost, w[previousNode][i] + memo(i, state ^(1 << i), c, w))
                }
            }
        }
        c[previousNode][state] = totalCost
        return totalCost
    }
    public func getTour(graph: Graph < V, E >):?GraphPath < V, E > {
        requireNotEmpty(graph)
        let n: Int64 = graph.vertexSet().size
        if(n == 1) {
            return getSingletonTour(graph)
        }
        if(n > 31) {
            throw IllegalArgumentException("The internal representation of the dynamic programming state space cannot represent graphs containing more than 31 vertices. The runtime complexity of this implementation, O(2^|V| x |V|^2),  makes it unsuitable for graphs with more than 31 vertices.")
        }
        let vertexToIntegerMapping: VertexToIntegerMapping < V >= Graphs.getVertexToIntegerMapping(graph)
        let w: ArrayList < ArrayList < Float64 >>= computeMinimumWeights(vertexToIntegerMapping.getVertexMap(), graph)
        let c: ArrayList < ArrayList < Float64 >>= ArrayList < ArrayList < Float64 >>(n, { _ => ArrayList < Float64 >(1 << n, { _ => Float64.Min }) })
        let tourWeight: Float64 = memo(0, 1, c, w)
        if(tourWeight == Float64.Max) {
            return None
        }
        let vertexList: ArrayList < V >= reconstructTour(vertexToIntegerMapping.getIndexList(), w, c)
        return vertexListToTour(vertexList, graph)
    }
    private func computeMinimumWeights(vertexMap: Map < V, Int64 >, graph: Graph < V, E >): ArrayList < ArrayList < Float64 >> {
        let n: Int64 = vertexMap.size
        let w: ArrayList < ArrayList < Float64 >>= ArrayList < ArrayList < Float64 >>(n, { _ => ArrayList < Float64 >(n, { _ => Float64.Inf }) })
        for(e in graph.edgeSet()) {
            let source: V = graph.getEdgeSource(e)
            let target: V = graph.getEdgeTarget(e)
            let u: Int64 = vertexMap[source]
            let v: Int64 = vertexMap[target]
            w[u][v] = min(w[u][v], graph.getEdgeWeight(e))
            if(graph.getType().isUndirected()) {
                w[v][u] = min(w[v][u], graph.getEdgeWeight(e))
            }
        }
        return w
    }
    private func reconstructTour(indexList: ArrayList < V >, w: ArrayList < ArrayList < Float64 >>, c: ArrayList < ArrayList < Float64 >>): ArrayList < V > {
        let n: Int64 = indexList.size
        let vertexList: ArrayList < V >= ArrayList < V >(n)
        var lastNode: Int64 = 0
        var lastState: Int64 = 1
        vertexList.append(indexList[lastNode])
        for(_ in 1 .. n) {
            var nextNode: Int64 = - 1
            for(node in 1 .. n) {
                let t: Float64 = c[node][lastState ^(1 << node)] + w[lastNode][node]
                if((lastState &(1 << node)) == 0 && w[lastNode][node] != Float64.Max && c[node][lastState ^(1 << node)] != Float64.Min &&(t == c[lastNode][lastState])) {
                    nextNode = node
                    break
                }
            }
            if(nextNode == - 1) {
                throw IllegalArgumentException("NextNode should not be equal to -1")
            }
            vertexList.append(indexList[nextNode])
            lastState ^= 1 << nextNode
            lastNode = nextNode
        }
        return vertexList
    }
}
