import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        var ciphertext = ""
        for(char in plaintext) {
            if(char >= 'a' && char <= 'z') {
                let shifted = ((char - 'a' + shift % 26 + 26) % 26) + 'a'
                ciphertext += String.fromCharCode(shifted)
            } else if(char >= 'A' && char <= 'Z') {
                let shifted = ((char - 'A' + shift % 26 + 26) % 26) + 'A'
                ciphertext += String.fromCharCode(shifted)
            } else {
                ciphertext += char
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        var ciphertext = ""
        let plain = plain_text.toLowerCase()
        let keyLower = this.key.toLowerCase()
        let keyLength = keyLower.size
        for(i in 0 .. plain.size) {
            if(i >= keyLength) break
            let plainChar = plain[i]
            if(plainChar >= 'a' && plainChar <= 'z') {
                let keyChar = keyLower[i % keyLength]
                let shift = keyChar - 'a'
                let cipherChar = ((plainChar - 'a' + shift) % 26) + 'a'
                ciphertext += String.fromCharCode(cipherChar)
            } else {
                ciphertext += plainChar
            }
        }
        return ciphertext
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        if(rails <= 1) return plain_text
        let railArrays = ArrayList < ArrayList < Char > >()
        for(i in 0 .. rails) {
            railArrays.add(ArrayList < Char >())
        }
        var currentRail = 0
        var goingDown = true
        for(char in plain_text) {
            railArrays[currentRail].add(char)
            if(goingDown) {
                currentRail += 1
                if(currentRail == rails - 1) {
                    goingDown = false
                }
            } else {
                currentRail -= 1
                if(currentRail == 0) {
                    goingDown = true
                }
            }
        }
        var ciphertext = ""
        for(rail in railArrays) {
            for(c in rail) {
                ciphertext += c
            }
        }
        return ciphertext
    }
}

