        return CacheConfig().setHttpCacheEnabled(true).setMemoryCacheEnabled(true).setDefaultMaxAge(3600)
    }
    public static func createHighPerformanceConfig(): CacheConfig {
        return CacheConfig().setHttpCacheEnabled(true).setMemoryCacheEnabled(true).setDefaultMaxAge(7200).setMaxCacheSize(500 * 1024 * 1024).setMaxEntries(50000)
    }
