    }
    public static func generateCacheKey(path: String, params: HashMap < String, String >): String {
        var key = path
        if(params.size > 0) {
            key += "?"
            var first = true
            for((paramKey, value) in params) {
                if(! first) {
                    key += "&"
                }
                key += "${paramKey}=${value}"
                first = false
            }
        }
        return key
    }
    public static func isCacheable(contentType: String): Bool {
        let cacheableTypes =["text/html", "text/css", "text/javascript", "application/javascript", "application/json", "image/jpeg", "image/png", "image/gif"]
        for(cacheableType in cacheableTypes) {
            if(contentType.startsWith(cacheableType)) {
                return true
            }
        }
        return false
    }
    public static func getDefaultMaxAge(contentType: String): Int64 {
        if(contentType.startsWith("image/")) {
            return 86400
        }
        else if(contentType.startsWith("text/css") || contentType.startsWith("application/javascript")) {
            return 3600
        }
        else if(contentType.startsWith("text/html")) {
            return 300
        }
        else {
            return 1800
        }
    }
    public static func isValidCacheKey(key: String): Bool {
