import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2]) // order: +, -, *, /, (, ), %, space
    }

    public func calculate(expression: String): Float64 {
        let infix = transform(expression: expression)
        prepare(expression: infix)
        let operator_stack = ArrayList<String>()
        let result_stack = ArrayList<Decimal>()

        for token in postfix_stack {
            if !is_operator(c: token) {
                result_stack.push(Decimal.parse(token))
            } else {
                let second_value = result_stack.pop()
                let first_value = result_stack.pop()
                let res = _calculate(first_value: first_value, second_value: second_value, current_op: token)
                result_stack.push(res)
            }
        }

        return result_stack.pop().toFloat64()
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let operator_stack = ArrayList<String>()
        let tokens = Regex.split(expression, r"\s+").filter(!_.isEmpty())

        for token in tokens {
            if !is_operator(c: token) {
                postfix_stack.push(token)
            } else if token == "(" {
                operator_stack.push(token)
            } else if token == ")" {
                while operator_stack.last() != "(" {
                    postfix_stack.push(operator_stack.pop())
                }
                operator_stack.pop() // Remove '(' from stack
            } else {
                while operator_stack.size() > 0 && 
                      compare(cur: token, peek: operator_stack.last()) && 
                      operator_stack.last() != "(" {
                    postfix_stack.push(operator_stack.pop())
                }
                operator_stack.push(token)
            }
        }

        while operator_stack.size() > 0 {
            postfix_stack.push(operator_stack.pop())
        }
    }

    public static func is_operator(c: String): Bool {
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        let map: Map<String, Int64> = [
            "+": 0, 
            "-": 1, 
            "*": 2, 
            "/": 3, 
            "(": 4, 
            ")": 5, 
            "%": 6
        ]
        let idx_cur = map[cur] ?? -1
        let idx_peek = map[peek] ?? -1
        return operat_priority[idx_cur] >= operat_priority[idx_peek]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        switch current_op {
            case "+": return first_value + second_value
            case "-": return first_value - second_value
            case "*": return first_value * second_value
            case "/": return first_value / second_value
            case "%": return first_value % second_value
            default: return Decimal.zero()
        }
    }

    public static func transform(expression: String): String {
        let trimmed = expression.replace(" ", "")
        let builder = StringBuilder()
        var i = 0
        let n = trimmed.size()

        while i < n {
            let c = trimmed[i]
            if c.isDigit() || c == '.' {
                while i < n && (trimmed[i].isDigit() || trimmed[i] == '.') {
                    builder.append(trimmed[i])
                    i += 1
                }
                builder.append(" ")
            } else if is_operator(c: String(c)) {
                builder.append(String(c))
                i += 1
                builder.append(" ")
            } else {
                i += 1
            }
        }

        return builder.toString().trim()
    }
}

