import std.collection.ArrayList

class Interpolation {

    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let y_interp = ArrayList<Float64>()
        for(xval in x_interp) {
            // Find the segment where xval lies
            var i: Int64 = 0
            while(i < x.size - 1 && x[i + 1] < xval) {
                i += 1
            }
            if(i >= x.size - 1) {
                i = x.size - 2
            }
            if(x[i] == xval) {
                y_interp.append(y[i])
                continue
            }
            if(x[i + 1] == xval) {
                y_interp.append(y[i + 1])
                continue
            }
            // Linear interpolation
            let x0 = x[i]
            let x1 = x[i + 1]
            let y0 = y[i]
            let y1 = y[i + 1]
            let y_val = y0 + (y1 - y0) * (xval - x0) / (x1 - x0)
            y_interp.append(y_val)
        }
        return y_interp
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let z_interp = ArrayList<Float64>()
        for(xval in x_interp) {
            for(yval in y_interp) {
                // Find x segment
                var xi: Int64 = 0
                while(xi < x.size - 1 && x[xi + 1] < xval) {
                    xi += 1
                }
                if(xi >= x.size - 1) {
                    xi = x.size - 2
                }
                if(x[xi] == xval) {
                    // Find y segment for this x segment
                    var yi: Int64 = 0
                    while(yi < y.size - 1 && y[yi + 1] < yval) {
                        yi += 1
                    }
                    if(yi >= y.size - 1) {
                        yi = y.size - 2
                    }
                    if(y[yi] == yval) {
                        z_interp.append(z[xi][yi])
                    } else {
                        // Linear interpolation in y direction
                        let y0 = y[yi]
