        let url = URL.parse(address)
        let builder = ServerBuilder().addr(url.hostName).port(UInt16.parse(url.port.toString())).distributor(DefaultHttpRequestDistributor(app, _services))
        let server = builder.build()
        _server = server
        server.logger.level = StdLogLevel.OFF
        logStarted(address)
        server.serve()
    }
    private func getServerAddress() {
        let ip = if(isRunningInContainer()) {
            "0.0.0.0"
        }
        else {
            "127.0.0.1"
        }

        let configuration = _services.getOrThrow < IConfiguration >()
        if(let Some(urls) <- configuration.getValue < String >("urls")) {
            urls
        }
        else if(let Some(port) <- configuration.getValue < String >("HTTP_PORTS")) {
            "http://${ip}:${port}"
        }
        else {
            "http://${ip}:5000"
        }
    }
    private func logStarted(address: String) {
        let loggerFactory = _services.getOrThrow < ILoggerFactory >()
        let environment = _services.getOrThrow < IWebHostEnvironment >()
        let logger = loggerFactory.createLogger("spire.hosting.lifetime")
        logger.info("Now listening on: ${address}")
        logger.info("Hosting environment: ${environment.environmentName}")
        logger.info("Content root path: ${environment.contentRootPath}")
        logger.info("Application started. Press Ctrl+C to shut down.")
    }
    private func isRunningInContainer() {
        if(let Some(value) <- getVariable("CANGJIE_RUNNING_IN_CONTAINER")) {
            return value.equalsIgnoreAsciiCase("true")
        }
        return false
    }
