public class CacheLineUtils {
    public static let CACHE_LINE_SIZE: Int64 = 64
    public static func alignToCacheLine(size: Int64): Int64 {
        let remainder = size % CACHE_LINE_SIZE
        if(remainder == 0) {
            return size
        }
        return size +(CACHE_LINE_SIZE - remainder)
    }
    public static func isCacheLineAligned(address: Int64): Bool {
        return address % CACHE_LINE_SIZE == 0
    }
