        return(address / CACHE_LINE_SIZE) * CACHE_LINE_SIZE
    }
    public static func inSameCacheLine(addr1: Int64, addr2: Int64): Bool {
        return getCacheLineBoundary(addr1) == getCacheLineBoundary(addr2)
    }
