        }
        let job = CronJob.parse(name, cronExp, fn)
        _jobs.add(name, job)
        @LogInfo
        ("[Schedule] add crontab job, name=${name}")
    }
    public func addJobIfAbsent(name: String, cronExp: String, fn: ScheduleFunc): Unit {
