class MNISTLoader {
    var imagePath: String = ""
    var labelPath: String = ""
    public init(imgPath: String, labelPath: String) {
        this.imagePath = imgPath
        this.labelPath = labelPath
    }
    public func unpackI32(buffer: Array < UInt8 >, offset: Int32): Int32 {
        return(Int32(buffer[Int64(offset)])) << 24 |(Int32(buffer[Int64(offset + 1)])) << 16 |(Int32(buffer[Int64(offset + 2)])) << 8 |(Int32(buffer[Int64(offset + 3)]))
    }
    func loadImages(): Array < Array < Float32 >> {
        let file = File(this.imagePath, OpenOption.Open(true, false))
        let buffers = file.readToEnd()
        file.close()
        let imgNum = unpackI32(buffers, 4)
        let width = unpackI32(buffers, 8)
        let height = unpackI32(buffers, 12)
        let offset = Int32(16)
        let pixelCount = width * height
        let images = Array < Array < Float32 >>(Int64(imgNum), item: Array < Float32 >())
        for(i in 0 ..= imgNum - 1) {
            let row = Array < Float32 >(Int64(pixelCount), item: 0.0)
            let baseIdx = Int64(offset + i * pixelCount)
            for(j in 0 ..= pixelCount - 1) {
                row[Int64(j)] = Float32(buffers[baseIdx + Int64(j)]) / 255.0
            }
            images[Int64(i)] = row
        }
        return images
    }
    func loadLabels(): Array < Array < Float32 >> {
        let file = File(this.labelPath, OpenOption.Open(true, false))
        let buffers = file.readToEnd()
        file.close()
        let labelNum = unpackI32(buffers, 4)
        let offset = Int32(8)
        let labels = Array < Array < Float32 >>(Int64(labelNum), item: Array < Float32 >())
        for(i in 0 ..= labelNum - 1) {
            let oneHot = Array < Float32 >(10, item: 0.0)
            let label = buffers[Int64(offset + i)]
            oneHot[Int64(label)] = 1.0
            labels[Int64(i)] = oneHot
        }
        return labels
    }
    func loadData():(Array < Array < Float32 >>, Array < Array < Float32 >>) {
        let images = this.loadImages()
        let labels = this.loadLabels()
        return(images, labels)
    }
}
