import std.collection.ArrayList
import std.math.abs

class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        if(data is Tuple2<ArrayList<Int64>, Int64>) {
            let (actual, groundTruthNum) = data as! Tuple2<ArrayList<Int64>, Int64>
            let reciprocals = ArrayList<Float64>()
            for(i in 0 ..< actual.size) {
                if(actual[i] == 1) {
                    reciprocals.append(1.0 / Float64(i + 1))
                }
            }
            if(reciprocals.isEmpty()) {
                return (0.0, ArrayList<Float64>([0.0]))
            }
            let mrrValue = reciprocals[0]
            let precisionList = ArrayList<Float64>([mrrValue])
            return (mrrValue, precisionList)
        } else if(data is ArrayList<Tuple2<ArrayList<Int64>, Int64>>) {
            let dataList = data as! ArrayList<Tuple2<ArrayList<Int64>, Int64>>
            var totalReciprocal = 0.0
            var precisionValues = ArrayList<Float64>()
            for(item in dataList) {
                let (actual, groundTruthNum) = item
                var reciprocal: Float64 = 0.0
                var found = false
                for(i in 0 ..< actual.size) {
                    if(actual[i] == 1) {
                        reciprocal = 1.0 / Float64(i + 1)
                        found = true
                        break
                    }
                }
                if(found) {
                    totalReciprocal += reciprocal
                    precisionValues.append(reciprocal)
                } else {
                    precisionValues.append(0.0)
                }
            }
            let mrrValue = totalReciprocal / Float64(precisionValues.size)
            return (mrrValue, precisionValues)
        } else {
            return (0.0, ArrayList<Float64>([0.0]))
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        if(data is Tuple2<ArrayList<Int64>, Int64>) {
            let (actual, groundTruthNum) = data as! Tuple2<ArrayList<Int64>, Int64>
            var relevantItems = 0
            for(item in actual) {
                if(item == 1) {
                    relevantItems += 1
                }
            }
            if(relevantItems == 0) {
                return (0.0, ArrayList<Float64>([0.0]))
            }
            var precisionAtK = 0.0
            var sumPrecision = 0.0
            var relevantFound = 0
            for(k in 1 ..= actual.size) {
                if(actual[k - 1] == 1) {
                    relevantFound += 1
                    var truePositives = 0
                    for(i in 0 ..< k) {
                        if(actual[i] == 1) {
                            truePositives += 1
                        }
                    }
                    precisionAtK = Float64(truePositives) / Float64(k)
                    sumPrecision += precisionAtK
                }
            }
