import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        var minesPlaced = 0
        var positions = ArrayList<Pair<Int64, Int64>>()

        for i in 0..<n {
            var row = ArrayList<String>()
            for j in 0..<n {
                row.add("")
            }
            map.add(row)
        }

        for i in 0..<n {
            for j in 0..<n {
                positions.add(Pair(i, j))
            }
        }

        Random.shuffle(positions)

        for i in 0..<positions.size {
            if minesPlaced >= k {
                break
            }
            let pos = positions[i]
            map[pos.first][pos.second] = "X"
            minesPlaced++
        }

        for i in 0..<n {
            for j in 0..<n {
                if map[i][j] != "X" {
                    var count = 0
                    for di in -1..2 {
                        for dj in -1..2 {
                            let ni = i + di
                            let nj = j + dj
                            if ni >= 0 && ni < n && nj >= 0 && nj < n && map[ni][nj] == "X" {
                                count++
                            }
                        }
                    }
                    map[i][j] = String(count)
                }
            }
        }

        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>()
        for i in 0..<n {
            var row = ArrayList<String>()
            for _ in 0..<n {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for i in 0..<n {
            for j in 0..<n {
                if map[i][j] == "-" && minesweeper_map[i][j] != "X" {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if x < 0 || x >= n || y < 0 || y >= n {
            return player_map
        }

        if player_map[x][y] != "-" {
            return player_map
        }

        if minesweeper_map[x][y] == "X" {
            for i in 0..<n {
                for j in 0..<n {
                    if minesweeper_map[i][j] == "X" {
                        player_map[i][j] = "X"
                    }
                }
            }
            return false
        } else {
            player_map[x][y] = minesweeper_map[x][y]

            if check_won(player_map) {
                return true
            }
            return player_map
        }
    }
}

