import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let words_list = ArrayList<ArrayList<String>>()
        for s in string_list {
            let cleaned = Regex(pattern: "[^a-zA-Z ]").replace(text: s.lower(), replacement: "")
            let words = cleaned.split(separator: " ").filter { word -> word.size > 0 }
            words_list.add(ArrayList<String>(words))
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq_map = HashMap<String, Int64>()
        for words in words_list {
            for word in words {
                if freq_map.containsKey(word) {
                    freq_map[word] = freq_map[word]! + 1
                } else {
                    freq_map[word] = 1
                }
            }
        }
        let sorted_entries = ArrayList<HashMap.Entry<String, Int64>>(freq_map.entries())
        sort(sorted_entries, comparator: { a, b -> Int64 in
            if b.value == a.value {
                if a.key < b.key { -1 } else { 1 }
            } else {
                b.value - a.value
            }
        })
        let result = HashMap<String, Int64>()
        let max_items = 5
        for i in 0 .. (sorted_entries.size < max_items ? sorted_entries.size : max_items) {
            let entry = sorted_entries[i]
            result[entry.key] = entry.value
        }
        return result
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = process_data(string_list: string_list)
        return calculate_word_frequency(words_list: words_list)
    }
}

