import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    /*
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    */

    public init() {}

    public func replace(string: String): String {
        /*
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: String, the input string containing numeric character references.
        :return: String, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        */
        var result = ""
        var i = 0
        let n = string.length()
        while(i < n) {
            let char = string.charAt(i)
            if(char == r'&' && i + 2 < n && string.charAt(i + 1) == r'#') {
                var isHex = false
                var j = i + 2
                let startPos = j
                if(j < n && string.charAt(j) == r'x') {
                    isHex = true
                    j += 1
                }
                let numStrBuilder = StringBuilder()
                while(j < n) {
                    let currChar = string.charAt(j)
                    if((!isHex && Char.isDigit(currChar)) || 
                       (isHex && NumericEntityUnescaper.is_hex_char(currChar))) {
                        numStrBuilder.append(currChar)
                    } else if(currChar == r';') {
                        break
                    } else {
                        j = startPos - 1
                        break
                    }
                    j += 1
                }
                if(j < n && string.charAt(j) == r';') {
                    let numStr = numStrBuilder.toString()
                    if(numStr.isNotEmpty()) {
                        let num = isHex ? Int64.readInt(numStr, 16).getOrThrow() : Int64.readInt(numStr, 10).getOrThrow()
                        let unicodeChar = Rune.fromCodepoint(num.toInt())
                        result += unicodeChar.toString()
                        i = j + 1
                        continue
                    }
                } else {
                    // malformed entity, just append what we've collected
                    for(k in range(startPos, j)) {
                        result += string.charAt(k).toString()
                    }
                    i = j
                    continue
                }
            }
            result += char.toString()
            i += 1
        }
        return result
    }

    public static func is_hex_char(char: Rune): Bool {
        /*
        Determines whether a given character is a hexadecimal digit.
        :param char: Rune, the character to check.
        :return: Bool, true if the character is a hexadecimal digit, false otherwise.
        >>> NumericEntityUnescaper.is_hex_char(r'a')
        true

        */
        return (char >= r'0' && char <= r'9') ||
               (char >= r'A' && char <= r'F') ||
               (char >= r'a' && char <= r'f')
    }
}

