                    boxes_on_target = boxes_on_target + 1
                    break
                }
            }
        }
        this.is_game_over = boxes_on_target == this.target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        /*
        Move the player based on the specified direction and check if the game is won.
        :param direction: String, the direction of the player's movement. 
            It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.

        :return: true if the game is won, false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])]))       
        >>> game.print_map()
        # # # # # 
        # O     #
        #   X   #
        #     G #
        # # # # #
        >>> game.move('d')
        false
        >>> game.move('s')   
        false
        >>> game.move('a')   
        false
        >>> game.move('s') 
        false
        >>> game.move('d') 
        true
        */
        var new_row: Int64 = this.player_row
        var new_col: Int64 = this.player_col
        switch direction {
            case "w" -> new_row = this.player_row - 1
            case "s" -> new_row = this.player_row + 1
            case "a" -> new_col = this.player_col - 1
            case "d" -> new_col = this.player_col + 1
            default -> { return false }
        }

        var box_row: Int64 = -1
        var box_col: Int64 = -1
        for box_pos in this.boxes {
            if box_pos[0] == new_row && box_pos[1] == new_col {
                box_row = new_row
                box_col = new_col
                break
            }
        }

        if new_row < 0 || new_row >= this.map.size() || new_col < 0 || new_col >= this.map[0].size() {
            return false
        }

        if this.map[new_row][new_col] == "#" {
            return false
        }

        if box_row != -1 && box_col != -1 {
            var next_row = new_row
            var next_col = new_col
            switch direction {
                case "w" -> next_row = new_row - 1
                case "s" -> next_row = new_row + 1
                case "a" -> next_col = new_col - 1
                case "d" -> next_col = new_col + 1
                default -> {}
            }

            if next_row < 0 || next_row >= this.map.size() || next_col < 0 || next_col >= this.map[0].size() {
                return false
            }

            if this.map[next_row][next_col] == "#" {
                return false
            }

            for box_pos in this.boxes {
                if box_pos[0] == next_row && box_pos[1] == next_col {
                    return false
                }
            }

            for i in 0..<this.boxes.size() {
                if this.boxes[i][0] == box_row && this.boxes[i][1] == box_col {
                    this.boxes[i][0] = next_row
                    this.boxes[i][1] = next_col
                    break
                }
            }
        }

        this.player_row = new_row
        this.player_col = new_col

        return this.check_win()
    }
