        while(matcher.find()) {
            result.add(matcher.group())
        }
        result
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let result = ArrayList<String>()
        let parts = Regex(pattern).split(text)
        for(part in parts) {
            result.add(part)
        }
        result
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        Regex(pattern).replaceAll(text, replacement)
    }

    public func generate_email_pattern(): String {
        #'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'#
    }

    public func generate_phone_number_pattern(): String {
        #'\b\d{3}-\d{3}-\d{4}\b'#
    }

    public func generate_split_sentences_pattern(): String {
        #"[.!?][\s]{1,2}(?=[A-Z])"#
    }

    public func split_sentences(text: String): ArrayList<String> {
        let result = ArrayList<String>()
        let pattern = generate_split_sentences_pattern()
        let sentences = Regex(pattern).split(text)
        for(i in 0..<sentences.size - 1) {
            let sentence = sentences[i].trim()
            let lastChar = sentence[sentence.size - 1]
            if(lastChar == '.' || lastChar == '!' || lastChar == '?') {
                result.add(sentence)
            }
            else {
                let lastPunct = findall(#'[.!?]'$#, sentence)
                if(lastPunct.size > 0) {
                    result.add(sentence)
                }
                else {
                    result.add(sentence.sub(#'[.!?]\s*$'#, ""))
                }
            }
        }
        if(sentences.size > 0) {
            result.add(sentences[sentences.size - 1].trim())
        }
        result
    }

    public func validate_phone_number(phone_number: String): Bool {
        match_regex(generate_phone_number_pattern(), phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        findall(generate_email_pattern(), text)
    }
}

