import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let regex = Regex("(?<=[.!?])\\s+(?!\\s*$)")
        let matcher = regex.matcher(sentences_string)
        let sentences = ArrayList<String>()
        let splitResults = matcher.split()
        for(i in 0 .. splitResults.size) {
            if(i < splitResults.size - 1) {
                sentences.add(splitResults[i].trimAscii())
            } else if(i == splitResults.size - 1 && splitResults[i].trimAscii().length() > 0) {
                sentences.add(splitResults[i].trimAscii())
            }
        }
        if(sentences.size == 0 && sentences_string.trimAscii().length() > 0) {
            sentences.add(sentences_string.trimAscii())
        }
        return sentences
    }

    public func count_words(sentence: String): Int64 {
        let trimmedSentence = sentence.trimAscii()
        if(trimmedSentence.length() == 0) {
            return 0
        }
        let regex = Regex("[^\\s]+")
        let matcher = regex.matcher(trimmedSentence)
        var count: Int64 = 0
        while(matcher.find()) {
            count += 1
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = this.split_sentences(sentences_string)
        var maxCount: Int64 = 0
        for(sentence in sentences) {
            let currentCount = this.count_words(sentence)
            if(currentCount > maxCount) {
                maxCount = currentCount
            }
        }
        return maxCount
    }
}

