import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.isEmpty()) {
            return Float64.NaN
        }
        var sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        var freq = HashMap<Int64, Int64>()
        for num in data {
            freq[num] = freq.getOrDefault(num, 0) + 1
        }
        var maxCount = 0
        var modes = ArrayList<Int64>()
        for (num, count) in freq {
            if (count > maxCount) {
                maxCount = count
                modes.clear()
                modes.add(num)
            } else if (count == maxCount) {
                modes.add(num)
            }
        }
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.isEmpty() || y.isEmpty() || x.size != y.size) {
            return Option.None
        }
        var xMean = mean(x) ?: return Option.None
        var yMean = mean(y) ?: return Option.None
        var numerator = 0.0
        var xSumSq = 0.0
        var ySumSq = 0.0
        for i in 0 ..< x.size {
            let xVal = Float64(x[i]) - xMean
            let yVal = Float64(y[i]) - yMean
            numerator += xVal * yVal
            xSumSq += xVal * xVal
            ySumSq += yVal * yVal
        }
        let denominator = sqrt(xSumSq * ySumSq)
        return Option.Some(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.isEmpty()) {
            return Option.None
        }
        var sum = 0
        for num in data {
            sum += num
        }
        return Option.Some(Float64(sum) / Float64(data.size))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        var matrix = ArrayList<ArrayList<Float64>>()
        for i in 0 ..< data.size {
            var row = ArrayList<Float64>()
            for j in 0 ..< data.size {
                let corr = correlation(data[i], data[j]) ?: 0.0
                row.add(corr)
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        if (data.isEmpty()) {
            return Option.None
        }
        var m = mean(data) ?: return Option.None
        var sumSq = 0.0
        for num in data {
            sumSq += pow(Float64(num) - m, 2)
        }
        return Option.Some(sqrt(sumSq / Float64(data.size)))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        if (data.isEmpty()) {
            return Option.None
        }
        var m = mean(data) ?: return Option.None
        var std = standard_deviation(data) ?: return Option.None
        if (std == 0.0) {
            return Option.None
        }
        var zScores = ArrayList<Float64>()
        for num in data {
            zScores.add((Float64(num) - m) / std)
        }
        return Option.Some(zScores)
    }
}

