import std.math.abs

class Stock <: Equatable<Stock> {

    let name: String
    var price: Float64
    var quantity: Int64

    public init(name: String, price: Float64, quantity: Int64) {
        this.name = name
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Stock): Bool {
        return this.name != that.name || this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Stock): Bool {
        return this.name == that.name && this.price == that.price && this.quantity == that.quantity
    }
}

class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        this.portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        for i in 0 ..< this.portfolio.length() {
            if this.portfolio.get(i) == stock {
                this.portfolio.remove(i)
                return true
            }
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let total_cost = stock.price * Float64(stock.quantity)
        if this.cash_balance >= total_cost {
            this.cash_balance -= total_cost
            this.portfolio.add(stock)
            return true
        }
        return false
    }

    public func sell_stock(stock: Stock): Bool {
        for i in 0 ..< this.portfolio.length() {
            if this.portfolio.get(i) == stock {
                let total_value = stock.price * Float64(stock.quantity)
                this.cash_balance += total_value
                this.portfolio.remove(i)
                return true
            }
        }
        return false
    }

    public func calculate_portfolio_value(): Float64 {
        let portfolio_value = this.portfolio.foldl(0.0) { sum, stock -> Float64 {
            sum + stock.price * Float64(stock.quantity)
        }}
        return portfolio_value + this.cash_balance
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        let summary_list = ArrayList<HashMap<String, Any>>()
        let portfolio_value = this.portfolio.foldl(0.0) { sum, stock -> Float64 {
            let stock_value = stock.price * Float64(stock.quantity)
            let entry = HashMap<String, Any>()
            entry.put("name", stock.name)
            entry.put("value", stock_value)
            summary_list.add(entry)
            return sum + stock_value
        }}
        let total_value = portfolio_value + this.cash_balance
        return (total_value, summary_list)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * Float64(stock.quantity)
    }
}

