import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let radians = x * PI / 180.0
        return taylor(radians, 50)
    }

    public func factorial(a: Int64): Decimal {
        var result: Decimal = 1
        if(a == 0 || a == 1) {
            return result
        }
        for i in 2..a + 1 {
            result = result * Decimal(of: i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var sum: Float64 = 0.0
        for i in 0..n {
            let term: Float64 = pow(-1.0, Float64(i)) * pow(x, Float64(2 * i)) / fromDecimal(factorial(2 * i))
            sum = sum + term
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
        let radians = x * PI / 180.0
        var sum: Float64 = 0.0
        for i in 0..50 {
            let term: Float64 = pow(-1.0, Float64(i)) * pow(radians, Float64(2 * i + 1)) / fromDecimal(factorial(2 * i + 1))
            sum = sum + term
        }
        return sum
    }

    public func tan(x: Float64): Option<Float64> {
        let cosValue = cos(x)
        if abs(cosValue) < 0.000001 {
            return Option.none()
        }
        let sinValue = sin(x)
        return Option.some(sinValue / cosValue)
    }
}

