                if (!val) {
                    return false
                }
            }
            return result == 24 || result == 24.0
        } catch (Exception e) {
            return false
        }
    }

    private func _process_expression(expr: String): (Int64, ArrayList<String>) {
        let processedNumbers = ArrayList<String>()
        var depth = 0
        var currentNumber = ""
        for (i in 0..<expr.size) {
            let ch = Rune(expr[i])
            if (ch == r'(') {
                depth++
            } else if (ch == r')') {
                depth--
            } else if (depth == 0 && ((ch >= r'0' && ch <= r'9') || (ch >= r'a' && ch <= r'd') || (ch >= r'A' && ch <= r'D'))) {
                currentNumber += ch.toString()
            } else if (currentNumber != "" && depth == 0) {
                processedNumbers.add(currentNumber)
                currentNumber = ""
            }
        }
        if (currentNumber != "" && depth == 0) {
            processedNumbers.add(currentNumber)
        }
        var balance = 0
        for (i in 0..<expr.size) {
            let ch = Rune(expr[i])
            if (ch == r'(') {
                balance++
            } else if (ch == r')') {
                balance--
            }
        }
        let numberCount = Int64(processedNumbers.size)
        return (numberCount, processedNumbers)
    }
}
