import std.collection.HashMap

class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let parts = url.split("://")
        if parts.size() >= 1 {
            return parts.get(0).getOrThrow()
        }
        return None
    }

    public func get_host(): Option<String> {
        let schemePart = get_scheme().getOrThrow()
        let remaining = url.substring(schemePart.size() + 3)
        let hostEnd = remaining.indexOfAny(['/', '?', '#'])
        if hostEnd >= 0 {
            return remaining.substring(0, hostEnd)
        }
        return remaining if remaining.size() > 0 else None
    }

    public func get_path(): Option<String> {
        let schemePart = get_scheme().getOrThrow()
        let remaining = url.substring(schemePart.size() + 3)
        let hostEnd = remaining.indexOf('/')
        if hostEnd >= 0 {
            let afterHost = remaining.substring(hostEnd)
            let pathEnd = afterHost.indexOfAny(['?', '#'])
            if pathEnd >= 0 {
                return afterHost.substring(0, pathEnd)
            }
            return afterHost
        }
        return None
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let pathPart = get_path().getOrThrow()
        let queryStart = pathPart.indexOf('?')
        if queryStart >= 0 {
            let queryStr = pathPart.substring(queryStart + 1)
            let fragmentStart = queryStr.indexOf('#')
            if fragmentStart >= 0 {
                queryStr = queryStr.substring(0, fragmentStart)
            }
            let params = HashMap<String, String>()
            let keyValues = queryStr.split('&')
            for kv in keyValues {
                let parts = kv.split('=')
                if parts.size() >= 2 {
                    let key = parts.get(0).getOrThrow().urlDecode()
                    let value = parts.get(1).getOrThrow().urlDecode()
                    params.put(key, value)
                } else if parts.size() == 1 {
                    let key = parts.get(0).getOrThrow().urlDecode()
                    params.put(key, "")
                }
            }
            return if params.size() > 0 then params else None
        }
        return None
    }

    public func get_fragment(): Option<String> {
        let schemePart = get_scheme().getOrThrow()
        let remaining = url.substring(schemePart.size() + 3)
        let hostAndPath = get_host().getOrNull() + get_path().getOrNull()
        if hostAndPath != null {
            let afterPath = url.substring(schemePart.size() + 3 + hostAndPath.size())
            let fragmentStart = afterPath.indexOf('#')
            if fragmentStart >= 0 {
                return afterPath.substring(fragmentStart + 1)
            }
        }
        return None
    }
}

