class FastPathTokenizer {
    public static func tokenize(path: String) {
        var count = calcSegmentCount(path)
        let segments = Array < PathSegment >(count, repeat: PathSegment(0, path.size))
        var start = 1
        for(i in 0 .. segments.size) {
            if(let Some(end) <- path.indexOf("/", start)) {
                segments[i] = PathSegment(start, end)
                start = end + 1
            }
            else {
                segments[i] = PathSegment(start, path.size)
            }
        }
        return segments
    }
    private static func calcSegmentCount(path: String) {
        var count = 1
        let runes = path.toRuneArray()
        for(i in 0 .. runes.size) {
            if(runes[i] == r'/') {
                if(i == 0 || i == runes.size - 1) {
                    continue
                }
                count ++
            }
        }
        return count
    }
}
